css:
:host{color-scheme:light;--bg-top:#0d3257;--bg-mid:#214463;--bg-bottom:#eee4d1;--sand:#f6ead4;--ink:#143254;--teal:#18b7b7;--gold:#c79a3e;--copper:#b56404;--mist:#dce8ee;--shadow:0 18px 40px rgba(8,18,31,.18);font-family:Manrope,"Segoe UI",sans-serif;color:var(--ink);background:var(--bg-top)}
*{box-sizing:border-box}
:host,[data-module-body]{width:100%;height:100%;max-width:100%;overflow:hidden;overscroll-behavior:none}
[data-module-body]{margin:0;background:radial-gradient(circle at top right,rgba(255,255,255,.12),transparent 23%),radial-gradient(circle at left 80%,rgba(255,183,77,.12),transparent 20%),linear-gradient(180deg,var(--bg-top) 0%,var(--bg-mid) 44%,var(--bg-bottom) 100%);color:var(--ink)}
.page-shell{height:100dvh;min-height:0;overflow:hidden;display:grid;justify-items:center;align-content:start;padding:max(8px,env(safe-area-inset-top,0px)) max(10px,env(safe-area-inset-right,0px)) max(8px,env(safe-area-inset-bottom,0px)) max(10px,env(safe-area-inset-left,0px))}
.app-frame{width:min(100%,430px);height:100%;min-height:0;margin:0 auto;display:grid;grid-template-rows:auto auto auto auto auto;align-content:space-between;gap:7px;overflow:hidden}
.hero-card,.card,.return-strip,.footer-banner{border-radius:22px;box-shadow:var(--shadow)}
.hero-card{display:flex;align-items:center;min-width:0;gap:12px;padding:16px 16px;background:linear-gradient(90deg,rgba(255,210,120,.4),rgba(232,217,187,.96));border:2px solid rgba(255,159,67,.72);box-shadow:0 16px 30px rgba(181,100,4,.2)}
.hero-logo-wrap{width:90px;height:90px;border-radius:20px;background:linear-gradient(145deg,#fff 0%,#e8f2f7 52%,#b9d0dc 100%);display:grid;place-items:center;flex:0 0 auto;border:1px solid rgba(255,255,255,.95);box-shadow:0 0 0 3px rgba(255,255,255,.48),0 12px 22px rgba(12,49,72,.22),inset 0 2px 0 rgba(255,255,255,.98)}
.hero-logo{width:78px;height:78px;object-fit:contain;filter:drop-shadow(0 6px 7px rgba(20,52,75,.2))}
.hero-copy{min-width:0;flex:1;text-align:center}.hero-kicker{display:block;font-size:.57rem;font-weight:900;letter-spacing:.12em;color:rgba(125,77,10,.96)}.hero-copy h1{margin:4px 0 0;font-size:clamp(1.25rem,5.4vw,1.7rem);line-height:1.05;font-weight:900;letter-spacing:.02em;color:var(--copper);text-shadow:2px 2px 5px rgba(122,57,0,.24)}
.card{border:1px solid rgba(255,255,255,.75);background:linear-gradient(140deg,rgba(255,249,238,.98),rgba(240,226,200,.98));padding:16px}.intro h2{font-size:clamp(1rem,4vw,1.18rem);line-height:1.16;margin:0 0 5px}.intro p{margin:0;font-size:.7rem;line-height:1.25}.identity{margin-top:7px;padding-top:7px;border-top:1px solid rgba(20,50,84,.14);font-size:.67rem;overflow-wrap:anywhere}.intro [data-auth-user]:not([hidden]){display:inline-flex}
#message{margin:0;padding:8px 10px;border-radius:12px;background:#fff2da;font-size:.7rem;line-height:1.25}#message:empty{display:none}
.scan{text-align:center;padding:18px 14px}.scan-symbol{display:grid;place-items:center;width:72px;height:72px;margin:0 auto 8px;color:var(--bg-top);border:2px solid rgba(199,154,62,.55);border-radius:16px;background:linear-gradient(145deg,#fff,#e1edf2);box-shadow:0 0 0 3px rgba(219,241,255,.55),0 8px 16px rgba(23,98,161,.12),inset 0 1px 0 #fff}.scan-symbol svg{width:52px;height:52px}.primary,.report-button,.soft{font:inherit;font-weight:850;border-radius:14px;min-height:46px;cursor:pointer;border:1px solid rgba(255,255,255,.76);padding:10px 14px;transition:transform 140ms ease,opacity 140ms ease,box-shadow 140ms ease}.primary:disabled,.report-button:disabled{opacity:.5;cursor:not-allowed}.primary:hover,.report-button:hover,.soft:hover{transform:translateY(-1px)}.primary{width:100%;color:#fff;background:linear-gradient(140deg,#28699a,#123b60);box-shadow:0 6px 14px rgba(20,50,84,.18),inset 0 1px 0 rgba(255,255,255,.34)}
.report-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px}.report-button{width:100%;min-height:56px;border:2px solid rgba(223,198,143,.95);background:linear-gradient(135deg,#f8edcf,#d2ae62);color:var(--ink);font-size:.66rem;letter-spacing:.06em;box-shadow:0 8px 14px rgba(181,100,4,.14),inset 0 1px 0 rgba(255,255,255,.8)}
.return-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;padding:6px;border:1px solid rgba(255,255,255,.86);background:linear-gradient(145deg,rgba(255,255,255,.86),rgba(218,232,239,.72));box-shadow:0 12px 24px rgba(8,18,31,.14),inset 0 1px 0 rgba(255,255,255,.96)}.return-strip a{position:relative;display:grid;grid-template-rows:1fr auto;justify-items:center;min-width:0;min-height:90px;padding:4px 2px 6px;border:1px solid rgba(255,255,255,.94);border-radius:15px;background:linear-gradient(160deg,rgba(255,255,255,.98),rgba(199,218,228,.9));color:#1762a1;text-decoration:none;box-shadow:0 6px 12px rgba(26,73,98,.12),inset 0 1px 0 #fff;transition:transform 140ms ease,box-shadow 140ms ease}.return-strip a:hover,.return-strip a:focus-visible{transform:translateY(-2px);box-shadow:0 0 0 2px rgba(219,241,255,.9),0 10px 18px rgba(23,98,161,.18)}.return-strip a:active{transform:translateY(1px) scale(.97)}.return-strip img{display:block;width:min(100%,64px);height:62px;object-fit:contain}.return-strip span{padding:2px 4px;border:1px solid rgba(23,98,161,.2);border-radius:999px;background:rgba(255,255,255,.64);font-size:.43rem;font-weight:900;letter-spacing:.03em;line-height:1;text-align:center}
.footer-banner{min-height:34px;display:flex;align-items:center;justify-content:center;padding:7px 8px;color:#fff;background:var(--teal);font-size:.53rem;font-weight:850;letter-spacing:.03em;text-align:center}
button:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #18b7b7;outline-offset:3px}[hidden]{display:none!important}
dialog{width:min(94%,560px);max-height:90dvh;overflow:auto;border:1px solid #fff;border-radius:22px;padding:24px;background:#fff9ed;color:var(--ink);box-shadow:var(--shadow)}dialog::backdrop{background:rgba(6,29,53,.73)}.dialog-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.dialog-head h2{margin:0}.dialog-head button{min-height:40px;padding:8px 12px;background:#e5ebee;color:var(--ink)}video{width:100%;border-radius:12px;background:var(--bg-top)}fieldset{padding:0;border:0;margin:20px 0}legend{font-weight:700;line-height:1.5}.choices{display:flex;gap:12px;margin-top:20px}.choices label{flex:1;border:1px solid;padding:18px;border-radius:12px;font-weight:800}.yes{color:#237a57;background:#e5f3e8}.no{color:#b52e36;background:#fce7e6}input[type=radio],input[type=checkbox]{width:20px;height:20px;vertical-align:middle;accent-color:var(--ink)}textarea,input[type=date]{display:block;width:100%;font:inherit;padding:12px;margin:8px 0 20px;border:1px solid #9eacb3;border-radius:10px;background:#fff;color:var(--ink)}textarea{resize:vertical}.unit-name{font-weight:800;font-size:20px}.declaration{display:flex;gap:10px;line-height:1.5;font-size:13px;margin:24px 0}.declaration input{flex-shrink:0}.signature{background:#e4ebef;border-radius:12px;padding:15px;font-size:13px}.monthly-button{margin-top:0}.monthly-day{padding:16px;border-radius:12px;background:#e8edf0;margin:12px 0;overflow-wrap:anywhere}.monthly-day h3{margin:0 0 12px}.monthly-day span{font-size:11px;font-weight:800;letter-spacing:1px}.monthly-day p{font-size:13px}.monthly-day .responsible-email{font-size:15px;font-weight:800}.monthly-day.checked .responsible-email{color:#166534}.monthly-day.pending .responsible-email{color:#b4232b}.monthly-day.checked{border-left:5px solid #237a57}.monthly-day.pending{border-left:5px solid #b52e36}.monthly-day button{width:100%;font-size:13px;background:#fff;color:var(--ink)}
@media(max-width:380px){.page-shell{padding-left:7px;padding-right:7px}.app-frame{gap:5px}.hero-card{padding:9px 10px;gap:9px}.hero-logo-wrap{width:64px;height:64px;border-radius:17px}.hero-logo{width:56px;height:56px}.hero-kicker{font-size:.49rem}.hero-copy h1{font-size:1.16rem}.card{padding:9px}.intro h2{font-size:.94rem}.intro p,.identity{font-size:.6rem}.scan{padding:7px 10px}.scan-symbol{width:47px;height:47px;margin-bottom:5px}.scan-symbol svg{width:33px;height:33px}.primary,.report-button{min-height:42px;padding:8px 10px;font-size:.6rem}.return-strip{gap:3px;padding:4px}.return-strip a{min-height:66px;border-radius:12px}.return-strip img{width:45px;height:43px}.return-strip span{font-size:.36rem}.footer-banner{min-height:25px;padding:5px 4px;font-size:.44rem}}
/* Ajustes de leitura e aproveitamento vertical da tela inicial. */
.hero-card{min-height:122px;padding:20px 18px}.hero-logo-wrap{width:102px;height:102px}.hero-logo{width:88px;height:88px}.scan{min-height:170px;padding:22px 16px}.scan-symbol{width:88px;height:88px;margin-bottom:12px}.scan-symbol svg{width:64px;height:64px}.report-actions{grid-template-columns:1fr;gap:8px}.report-button{min-height:58px}#message[data-state="identifying"]{display:block;padding:13px 14px;border:2px solid #d39b28;background:linear-gradient(135deg,#fff8d7,#f4d36a);color:#7b4b00;font-size:1rem;font-weight:950;letter-spacing:.03em;text-align:center;box-shadow:0 0 0 3px rgba(244,211,106,.3),0 10px 20px rgba(181,100,4,.2);animation:identifying-pulse 1.1s ease-in-out infinite alternate}#message[data-state="identifying"]::before{content:"⌛ ";font-size:1.05em}@keyframes identifying-pulse{from{transform:scale(1);filter:saturate(1)}to{transform:scale(1.015);filter:saturate(1.16)}}
@media(max-width:380px){.hero-card{min-height:108px;padding:14px 12px}.hero-logo-wrap{width:82px;height:82px}.hero-logo{width:70px;height:70px}.scan{min-height:148px;padding:15px 12px}.scan-symbol{width:72px;height:72px}.scan-symbol svg{width:52px;height:52px}.report-button{min-height:52px}}
@media(max-width:430px){.hero-card{min-height:110px;padding:14px}.hero-logo-wrap{width:82px;height:82px}.hero-logo{width:70px;height:70px}.scan{min-height:148px;padding:14px 12px}.scan-symbol{width:72px;height:72px;margin-bottom:8px}.scan-symbol svg{width:52px;height:52px}.report-button{min-height:52px}.return-strip{padding:4px;gap:3px}.return-strip a{min-height:74px;padding:3px 2px 5px}.return-strip img{width:52px;height:50px}.footer-banner{min-height:28px;padding:5px 6px}}
/* O ícone é uma segunda área ativa para iniciar a leitura e o bloco ganha altura para ocupar o espaço livre. */
.scan{min-height:200px;padding:28px 16px;display:flex;flex-direction:column;justify-content:center;gap:6px}
.scan-symbol{appearance:none;font:inherit;padding:0;cursor:pointer;transition:transform 140ms ease,box-shadow 140ms ease,opacity 140ms ease}
.scan-symbol:not(:disabled):hover,.scan-symbol:not(:disabled):focus-visible{transform:translateY(-2px);box-shadow:0 0 0 4px rgba(219,241,255,.78),0 12px 22px rgba(23,98,161,.2),inset 0 1px 0 #fff}
.scan-symbol:disabled{cursor:not-allowed;opacity:.52}
@media(max-width:430px){.scan{min-height:180px;padding:22px 12px}.scan-symbol{width:84px;height:84px;margin-bottom:10px}.scan-symbol svg{width:60px;height:60px}}

/* Ajuste final de proporção da página inicial. */
.checklist-hero{min-height:138px;padding:24px 18px}
.checklist-hero .hero-copy h1{margin:0;font-size:clamp(1.32rem,5.6vw,1.78rem);text-transform:uppercase}
.return-strip{min-height:118px;padding:10px 8px;gap:8px}
.return-strip a{min-height:100px;padding:7px 3px 9px}
.return-strip img{width:min(100%,72px);height:72px}
@media(max-width:430px){
  .checklist-hero{min-height:124px;padding:15px 14px}
  .return-strip{min-height:94px;padding:7px 5px;gap:5px}
  .return-strip a{min-height:82px;padding:4px 2px 7px}
  .return-strip img{width:60px;height:58px}
}
/* Shared training-style navigation cards across the ecosystem. */
.module-link-card,
.return-strip a {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  padding: 10px 2px;
  border: 1px solid #e2e6df;
  border-radius: 15px;
  background: #fff;
  color: #12324f;
  text-decoration: none;
  box-shadow: none;
  font-size: clamp(.58rem, 2vw, .85rem);
  font-weight: 800;
  transition: transform 140ms ease, filter 140ms ease, box-shadow 140ms ease;
}

/* Título exibido sobre a faixa original da ilustração, sem alterar seus equipamentos. */
.arsenal-visual {
  position: relative;
  overflow: hidden;
}
.arsenal-visual-title {
  position: absolute;
  z-index: 3;
  top: 4px;
  left: 4px;
  width: min(39%, 510px);
  min-height: 10%;
  display: flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 0 0 12px 0;
  background: rgba(239, 248, 253, 0.97);
  color: #102c5a;
  font-family: Manrope, system-ui, sans-serif;
  font-size: clamp(0.72rem, 3.8vw, 1.55rem);
  font-weight: 900;
  line-height: 1.05;
  white-space: nowrap;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.7);
  box-shadow: 7px 5px 12px rgba(35, 81, 112, 0.08);
  pointer-events: none;
}
.arsenal-visual-image {
  position: relative;
  z-index: 1;
}
@media (max-width: 380px) {
  .arsenal-visual-title {
    top: 3px;
    left: 3px;
    width: 42%;
    padding-inline: 6px;
    font-size: 0.62rem;
  }
}

.module-link-card::before { display: none; }

.module-link-card__image,
.return-strip img {
  display: block;
  width: 40px;
  height: 40px;
  object-fit: contain;
}

.module-link-card span,
.return-strip span {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #12324f;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: normal;
  line-height: 1.15;
  text-align: center;
}

.module-link-card:hover,
.module-link-card:focus-visible,
.return-strip a:hover,
.return-strip a:focus-visible {
  filter: brightness(1.02);
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(26, 73, 98, .14);
}

.module-link-card:active,
.return-strip a:active {
  transform: translateY(1px) scale(.97);
}
@media(max-width:380px){
  .checklist-hero{min-height:118px;padding:13px 11px}
  .return-strip{min-height:88px;padding:6px 4px;gap:4px}
  .return-strip a{min-height:76px}
  .return-strip img{width:54px;height:52px}
}

/* Leitor QR compacto para códigos impressos em 2 x 2 cm. */
.camera-stage{position:relative;width:min(100%,360px);aspect-ratio:4/3;margin:0 auto;overflow:hidden;border-radius:18px;background:#0d3257;isolation:isolate;box-shadow:inset 0 0 0 1px rgba(255,255,255,.22),0 10px 24px rgba(13,50,87,.22)}
.camera-stage video{display:block;width:100%;height:100%;object-fit:cover}
.camera-frame{position:absolute;left:50%;top:50%;width:min(64%,220px);aspect-ratio:1;transform:translate(-50%,-50%);border:3px solid #f2c15a;border-radius:18px;box-shadow:0 0 0 9999px rgba(6,29,53,.42),inset 0 0 0 2px rgba(255,255,255,.72),0 0 18px rgba(242,193,90,.5);pointer-events:none}
.camera-frame::before,.camera-frame::after{content:"";position:absolute;inset:10px;border:2px solid transparent;border-top-color:#fff;border-left-color:#fff;border-radius:8px;opacity:.86}
.camera-frame::after{transform:rotate(180deg)}
.camera-hint{margin:12px 0 0;text-align:center;color:#38566e;font-size:13px;font-weight:750;line-height:1.4}
@media(max-width:430px){.camera-stage{width:100%;max-width:330px}.camera-frame{width:min(68%,210px)}.camera-hint{font-size:12px}}


/* Authentication indicator: red until the shared session is effectively validated. */
[data-auth-user][data-authenticated="false"]:not([hidden]) {
  --auth-dot-color: #ef4444;
  background-image: radial-gradient(circle, #ef4444 0 6px, transparent 7px);
}

.hero-copy > [data-auth-user][data-authenticated="false"]:not([hidden])::before {
  background: #ef4444;
  box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.18), 0 1px 4px rgba(153, 27, 27, 0.24);
}
/* auth-authenticated-state */


/* Cabeçalho: somente o e-mail autenticado, abaixo do título. */
.checklist-hero .hero-copy > [data-auth-user]:not([hidden]) {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  color: #1769aa;
  font-size: .72rem;
  font-weight: 800;
  overflow-wrap: anywhere;
}
.checklist-hero .hero-copy > [data-auth-user]:not([hidden])::before {
  content: "";
  flex: 0 0 12px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 2px rgba(34,197,94,.18);
}
.checklist-hero .hero-copy > [data-auth-user][data-authenticated="false"]:not([hidden])::before {
  background: #ef4444;
  box-shadow: 0 0 0 2px rgba(239,68,68,.18);
}

/* Ilustração didática do arsenal no lugar do texto introdutório. */
.arsenal-visual {
  padding: 10px;
  overflow: hidden;
}.arsenal-visual-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 42vh;
  object-fit: contain;
  border-radius: 14px;
}
@media (max-width: 430px) {
  .arsenal-visual { padding: 6px; }
  .arsenal-visual-image { max-height: 34vh; border-radius: 11px; }
}


/* Prioriza a imagem inteira e libera espaço para os controles essenciais. */
.arsenal-visual { padding: 4px; }
.arsenal-visual-image { max-height: 38vh; width: 100%; object-fit: contain; }
.scan { min-height: 124px; padding: 10px 12px; gap: 4px; }
.scan-symbol { width: 56px; height: 56px; margin-bottom: 4px; }
.scan-symbol svg { width: 40px; height: 40px; }
.report-actions { grid-template-columns: 1fr; }
.report-button { min-height: 42px; padding: 7px 10px; }
@media (max-width: 430px) {
  .arsenal-visual-image { max-height: 38vh; }
  .scan { min-height: 112px; padding: 8px 10px; }
  .scan-symbol { width: 50px; height: 50px; }
  .scan-symbol svg { width: 36px; height: 36px; }
  .report-button { min-height: 38px; }
}

/* Navegação premium: cartões separados, flutuantes e consistentes com a Home. */
.return-strip {
  gap: 7px;
  padding: 7px;
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255,255,255,.9), rgba(218,232,239,.72));
  box-shadow: 0 14px 26px rgba(8,18,31,.14), inset 0 1px 0 rgba(255,255,255,.96);
}
.return-strip a {
  position: relative;
  isolation: isolate;
  min-height: 84px;
  padding: 5px 3px 7px;
  overflow: hidden;
  border: 2px solid rgba(255,255,255,.96);
  border-radius: 16px;
  background: linear-gradient(145deg, #fff, #e4eef3 56%, #b8d0dc);
  box-shadow: 0 6px 0 #7898a8, 0 12px 18px rgba(26,73,98,.16), inset 0 1px 0 #fff;
  transition: transform 150ms ease, filter 150ms ease, box-shadow 150ms ease;
}
.return-strip a:nth-child(2) { background: linear-gradient(145deg, #f5fffd, #cbe9e2 58%, #91c6bb); box-shadow: 0 6px 0 #4c8f88, 0 12px 18px rgba(30,96,89,.16), inset 0 1px 0 #fff; }
.return-strip a:nth-child(3) { background: linear-gradient(145deg, #fffdf5, #f3e5c5 58%, #d8b879); box-shadow: 0 6px 0 #9a6b28, 0 12px 18px rgba(154,107,40,.16), inset 0 1px 0 #fff; }
.return-strip a:nth-child(4) { background: linear-gradient(145deg, #f8fbfc, #dbe3e8 58%, #b2c0c8); box-shadow: 0 6px 0 #687d89, 0 12px 18px rgba(52,67,77,.16), inset 0 1px 0 #fff; }
.return-strip a:hover,
.return-strip a:focus-visible { filter: saturate(1.08) brightness(1.03); transform: translateY(-2px); box-shadow: 0 8px 0 #7898a8, 0 17px 24px rgba(26,73,98,.2), inset 0 1px 0 #fff; }
.return-strip a:active { transform: translateY(4px) scale(.98); box-shadow: 0 2px 0 #7898a8, 0 6px 10px rgba(26,73,98,.14), inset 0 2px 4px rgba(13,50,87,.12); }
.return-strip img { width: min(100%, 56px); height: 52px; }
.return-strip span { padding: 2px 4px; border: 1px solid rgba(23,98,161,.2); border-radius: 999px; background: rgba(255,255,255,.68); color: #12324f; font-size: .5rem; line-height: 1; }
@media (max-width: 380px) { .return-strip { gap: 4px; padding: 5px; } .return-strip a { min-height: 72px; border-radius: 13px; } .return-strip img { height: 45px; } }

/* Relatório diário em primeiro plano: maior área de toque e volume 3D. */
.report-actions {
  margin-top: 8px;
  margin-bottom: 2px;
}

.report-button {
  min-height: 78px;
  padding: 16px 14px 18px;
  border: 2px solid rgba(255, 248, 220, .98);
  border-radius: 19px;
  background:
    linear-gradient(135deg, rgba(255,255,255,.3), transparent 42%),
    linear-gradient(145deg, #f0b94e 0%, #d1801e 55%, #a94d0b 100%);
  color: #fffdf4;
  font-size: clamp(.78rem, 3.6vw, 1rem);
  font-weight: 950;
  letter-spacing: .075em;
  text-shadow: 0 2px 2px rgba(87, 43, 0, .38);
  box-shadow:
    0 8px 0 #713006,
    0 16px 26px rgba(142, 65, 7, .28),
    inset 0 2px 0 rgba(255,255,255,.5),
    inset 0 -8px 14px rgba(117, 43, 0, .16);
  transition: transform 150ms ease, filter 150ms ease, box-shadow 150ms ease;
}

.report-button:hover:not(:disabled),
.report-button:focus-visible:not(:disabled) {
